import { Routes, Route, Navigate } from "react-router-dom";

/* USER WEBSITE */
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import Overview from "./components/Overview";
import WhatToExpect from "./components/WhatToExpect";
import TrainingEnvironment from "./components/TrainingEnvironment";
import Programs from "./components/Programs";
import TrainingVideos from "./components/TrainingVideos";
import Gallery from "./components/Gallery";
import Membership from "./components/Membership";
import Trainers from "./components/Trainers";
import Contact from "./components/Contact";
import Review from "./components/Review";

/* ADMIN */
import Login from "./admin/Login";
import Dashboard from "./admin/Dashboard";

/* ================= USER SITE ================= */
function UserSite() {
  return (
    <div id="top" className="bg-black text-white min-h-screen">
      <Navbar />
      <Hero />
      <Overview />
      <WhatToExpect />
      <TrainingEnvironment />

      <section id="programs"><Programs /></section>
      <section id="training-videos"><TrainingVideos /></section>
      <section id="gallery"><Gallery /></section>
      <section id="membership"><Membership /></section>
      <section id="trainers"><Trainers /></section>
      <section id="contact"><Contact /></section>
      <section id="reviews"><Review /></section>
    </div>
  );
}

/* ================= ADMIN PROTECTION ================= */
const ProtectedAdmin = ({ children }) => {
  const token = localStorage.getItem("adminToken");
  return token ? children : <Navigate to="/admin" replace />;
};

/* ================= APP ================= */
export default function App() {
  return (
    <Routes>
      {/* USER WEBSITE */}
      <Route path="/" element={<UserSite />} />

      {/* ADMIN LOGIN */}
      <Route path="/admin" element={<Login />} />

      {/* ADMIN DASHBOARD (PROTECTED) */}
      <Route
        path="/admin/dashboard"
        element={
          <ProtectedAdmin>
            <Dashboard />
          </ProtectedAdmin>
        }
      />

      {/* FALLBACK */}
      <Route path="*" element={<Navigate to="/" />} />
    </Routes>
  );
}
